**Audio chunk handler (add new function):**
```js
function handleAgentAudioChunk(data) {
  // Convert raw PCM linear16 24kHz to playable blob
  const blob = new Blob([data], { type: 'audio/wav' });
  // Create WAV header for raw PCM
  const url = URL.createObjectURL(buildWavFromPcm(data, 24000));
  audioQueue.push(url);
  if (!isPlaying) playNext();
}

function buildWavFromPcm(pcmData, sampleRate) {
  const samples = pcmData instanceof ArrayBuffer ? pcmData : pcmData.arrayBuffer();
  // 44-byte WAV header + PCM data
  const buf = new ArrayBuffer(44 + (pcmData.byteLength || 0));
  const view = new DataView(buf);
  const writeStr = (off, str) => { for (let i = 0; i < str.length; i++) view.setUint8(off + i, str.charCodeAt(i)); };
  writeStr(0, 'RIFF');
  view.setUint32(4, 36 + (pcmData.byteLength || 0), true);
  writeStr(8, 'WAVE');
  writeStr(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);    // PCM
  view.setUint16(22, 1, true);    // mono
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true); // byte rate
  view.setUint16(32, 2, true);    // block align
  view.setUint16(34, 16, true);   // bits per sample
  writeStr(36, 'data');
  view.setUint32(40, pcmData.byteLength || 0, true);
  new Uint8Array(buf, 44).set(new Uint8Array(pcmData instanceof ArrayBuffer ? pcmData : new ArrayBuffer(0)));
  return new Blob([buf], { type: 'audio/wav' });
}
```

